import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"CoreLib 动作","description":"","frontmatter":{},"headers":[],"relativePath":"modules/forge/corelib-actions.md","filePath":"modules/forge/corelib-actions.md","lastUpdated":0}`),a={name:`modules/forge/corelib-actions.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="corelib-动作" tabindex="-1">CoreLib 动作 <a class="header-anchor" href="#corelib-动作" aria-label="Permalink to “CoreLib 动作”">​</a></h1><p>EmakiForge 注册到 CoreLib 动作系统的动作段清单, 以及各段的用途, 参数, 配置写法与异常处理</p><p>前置条件: EmakiForge 启用后, 三个锻造物品刷新段会自动追加到 CoreLib 的动作注册表, 直接在配置的动作管道里引用即可. 它们分别用于重建锻造层, 刷新玩家背包里的锻造物品, 或在批量改配置之后刷新在线玩家的物品</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>这里只记录 EmakiForge 注册的段; CoreLib 自带的通用段见 <a href="./../corelib/actions.html">CoreLib 动作系统</a>. 现在段 ID 只用下表里的规范名, 不再提供旧别名. 旧的 <code>emakiforge_refresh_held</code> 现在写成 <code>forge_refresh_held</code>, 另外两个同理</p></div><h2 id="段-id" tabindex="-1">段 ID <a class="header-anchor" href="#段-id" aria-label="Permalink to “段 ID”">​</a></h2><table tabindex="0"><thead><tr><th>段 ID</th><th>用途</th><th>目标要求</th></tr></thead><tbody><tr><td><code>forge_refresh_held</code></td><td>刷新目标玩家主手上的锻造物品</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>forge_refresh_player</code></td><td>刷新目标玩家背包里的锻造物品</td><td><code>REQUIRED_ENTITY</code></td></tr><tr><td><code>forge_refresh_all</code></td><td>刷新全部在线玩家的锻造物品</td><td><code>NONE</code></td></tr></tbody></table><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to “参数”">​</a></h2><p>这三个段都不会读额外参数 (<code>parameters()</code> 是空列表), 段的分类 (<code>category()</code>) 都是 <code>forge</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | forge_refresh_held&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | forge_refresh_player&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 不需要目标, 可省略 source</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;forge_refresh_all&#39;</span></span></code></pre></div><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to “使用提示”">​</a></h2><ul><li><code>forge_refresh_held</code> 只处理主手物品, 目标玩家主手为空时该段跳过</li><li><code>forge_refresh_player</code> 必须提供一个玩家目标, 执行时由 EmakiForge 的刷新服务处理该玩家的背包</li><li><code>forge_refresh_all</code> 的目标要求是 <code>NONE</code>, 可以单独成为一条管道, 适合放在管理员的管道模板里, 或者配置变更后做批量刷新. 执行后等待异步刷新完成, 最长等 20 秒; 超时, 部分失败, 或者刷新期间配置的世代发生了变化, 都会以失败结束</li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};